        if warm is not None and warm.defer_cleanup_if_pending():
            # No gesture exists while warming. The connector will close its
            # own result when it finishes; do not race a half-built worker.
            with self._process_lock:process=self._process
            if process is not None:
                try:process.kill()
                except OSError:pass
            return
        touch=self._touch
        if touch is not None:
            try:touch.close()
            except Exception:pass
        with self._process_lock:process=self._process
        if process is not None:
            try:process.kill()
            except OSError:pass
        up=self._touch_up
        if up:
            try:
                subprocess.Popen([self.executable,'-s',self.serial,'shell',*up],stdin=subprocess.DEVNULL,
                    stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,creationflags=getattr(subprocess,'CREATE_NO_WINDOW',0))
            except OSError:pass
