            if requested is not None:
                if not isinstance(self._touch,MaaFrameworkTouch) or self._touch.client.ready.get('info',{}).get('input_methods')!=requested:
                    raise RuntimeError('기존 연결이 선택한 입력 방식과 다릅니다. 자동으로 다른 입력을 사용하지 않습니다.')
            return
