            self.input_diagnostics.update(skill_input_transport='android_touchscreen_tap',skill_previous_contact_released=True)
            self._shell(['input','touchscreen','tap',str(nx),str(ny)],timeout=3)
            self._skill_android_tap_pending=None
            self.input_diagnostics['skill_click_delivery'].update(command_completed=True,command_seconds=time.perf_counter()-started,game_effect_confirmed=False)
            self.input_trace.append(dict(action='ui_tap',native=[nx,ny],transport='android_touchscreen_tap',
                seconds=started-self._input_trace_started,duration_seconds=time.perf_counter()-started,
                scope='host_command_not_android_down_up_timestamps'))
