    def _background_use_skill(self,device,frame,slot):
        assert_action_active(self)
        if self._background_cancel.is_set() or background_battle_animating(frame) or slot not in background_ready_slots(frame):return False
        self.__dict__.pop('_background_skill_confirmed_frame',None)
        self._skill_before_frame=frame.copy()
        decision=getattr(self,'_last_background_skill_decision',None) or {}
        profiles=decision.get('profiles',[])
        self._skill_confirm_effects=set(profiles[slot].get('effects',[])) if slot<len(profiles) else set()
        snapshot=getattr(self,'_farming_error_snapshot',None)
        point=((.057+.0875*slot)*1600,740)
        if isinstance(snapshot,dict):
            snapshot.update(skill_before_image=frame.copy(),phase='background_skill_open',skill_input='click_then_use',skill_click_backend=device.capture_settings.get('background_skill_input_backend','controller'),skill_use_requested=False,skill_use_dispatched=False,skill_slot=slot,skill_tap=list(point),
                skill_native_tap=list(device.point(*point)),input_display=getattr(device,'input_diagnostics',{}))
            self._manual_error_snapshot=snapshot
        pressed=device.skill_tap(*point)
        if isinstance(snapshot,dict) and isinstance(pressed,Image.Image):snapshot['skill_open_pressed_image']=pressed.copy()
        allowed={'사용','사용하기','스킬사용','발동'}
        opened_at=time.monotonic();previous_use=None;popup_seen=False;missing_popup=0
        for attempt in range(5):
            if self._background_cancel.wait(.08):raise RuntimeError('재료 파밍을 중지했습니다.')
            after=device.capture()
            if isinstance(snapshot,dict):snapshot.update(input_observed_image=after.copy(),skill_popup_checks=attempt+1)
            boxes=background_skill_button_rects(after)
            if boxes is not None:popup_seen=True;missing_popup=0
            elif popup_seen:
                missing_popup+=1
                if missing_popup>=2:
                    if isinstance(snapshot,dict):snapshot.update(phase='background_skill_popup_lost_before_use',
                        skill_use_requested=False,skill_popup_lost_checks=missing_popup,failure_image=after.copy(),
                        failure_image_scope='skill_popup_lost_before_use',skill_after_image=after.copy())
                    raise RuntimeError('캐릭터 클릭 후 스킬 팝업이 사용하기 입력 전에 닫혔습니다. 재클릭하지 않고 중지합니다.')
            quick=self._background_fast_skill_button(after)
            if quick is not None:
                if isinstance(snapshot,dict):snapshot['skill_popup_image']=after.copy()
                if isinstance(snapshot,dict):snapshot.update(phase='background_skill_use',skill_use_candidate=list(quick),skill_use_candidate_native=list(device.point(*quick)),skill_use_source='two_label_fast_ocr',skill_popup_seconds=round(time.monotonic()-opened_at,3))
                stable=previous_use is not None and max(abs(quick[i]-previous_use[i]) for i in (0,1))<=4
                previous_use=quick
                settled=stable and time.monotonic()-opened_at>=.25
                if isinstance(snapshot,dict):snapshot.update(skill_button_stable=settled,skill_popup_stable_checks=attempt+1)
                if not settled:continue
                if isinstance(snapshot,dict):snapshot.update(skill_use_requested=True,skill_use_tap=list(quick),skill_use_native_tap=list(device.point(*quick)))
                pressed=device.skill_tap(*quick)
                if isinstance(snapshot,dict):
                    snapshot['skill_use_dispatched']=True
                    if isinstance(pressed,Image.Image):snapshot['skill_use_pressed_image']=pressed.copy()
                break
            direct=self._background_skill_button_text(after,snapshot)
            if direct is not None:
                source='button_crop_ocr';use=direct
            else:
                tokens=self._run_ocr_tokens(after)
                matches=[t for t in tokens if t.score>=.90 and _compact_ocr_text(t.text) in allowed and t.cy>after.height*.45]
                close=[t for t in tokens if t.score>=.85 and _compact_ocr_text(t.text)=='닫기']
                if isinstance(snapshot,dict):snapshot['skill_popup_tokens']=[dict(text=t.text,score=round(float(t.score),3),center=[float(t.cx),float(t.cy)]) for t in tokens if t.cx<850 and t.cy>250]
                if len(matches)>1:raise RuntimeError('스킬 사용하기 버튼이 여러 개여서 파밍을 중지했습니다.')
                if not (len(matches)==1 and close):
                    previous_use=None;continue
                use=(matches[0].cx,matches[0].cy);source='full_frame_ocr'
            stable=previous_use is not None and max(abs(use[i]-previous_use[i]) for i in (0,1))<=4 and time.monotonic()-opened_at>=.25
            previous_use=use
            if isinstance(snapshot,dict):snapshot.update(skill_popup_image=after.copy(),skill_button_stable=stable)
            if not stable:continue
            if isinstance(snapshot,dict):snapshot.update(phase='background_skill_use',skill_use_tap=list(use),skill_use_native_tap=list(device.point(*use)),skill_use_source=source,skill_popup_seconds=round(time.monotonic()-opened_at,3))
            if isinstance(snapshot,dict):snapshot['skill_use_requested']=True
            pressed=device.skill_tap(*use)
            if isinstance(snapshot,dict):
                snapshot['skill_use_dispatched']=True
                if isinstance(pressed,Image.Image):snapshot['skill_use_pressed_image']=pressed.copy()
            break
        else:raise RuntimeError('스킬 사용 화면을 확인하지 못해 파밍을 멈췄습니다.')
        return self._background_confirm_skill(device,slot,snapshot)

    def _background_confirm_skill(self,device,slot,snapshot=None):
        # Only observe after one use click. A closed popup alone proves nothing.
        started=time.monotonic();popup=False;previous=None;history=[];counter_cache={};timer_cache={};timer_cache_hits=0
        before=getattr(self,'_skill_before_frame',None)
        baseline=background_skill_board_sample(before) if isinstance(before,Image.Image) else None
        effects=getattr(self,'_skill_confirm_effects',set())
        def timer(image):
            nonlocal timer_cache_hits
            digits=np.asarray(image.crop((1528,202,1573,247)).convert('RGB'));yy,xx=np.ogrid[:45,:45]
            key=hashlib.sha256(digits[(xx-22)**2+(yy-22)**2<=18**2].tobytes()).hexdigest()
            if key in timer_cache:
                timer_cache_hits+=1;return timer_cache[key]
            self._restricted_drag_move_cap(image=image,report=False)
            value=getattr(self,'_last_timer_read',{}).get('seconds')
            if value is not None:timer_cache[key]=value
            return value
        baseline_time=timer(before) if 'time' in effects and isinstance(before,Image.Image) else None
        for attempt in range(12):
            if attempt and time.monotonic()-started>=4.0:break
            if self._background_cancel.wait(.10 if attempt==0 else .25):raise RuntimeError('재료 파밍을 중지했습니다.')
            current=device.capture();captured_at=time.monotonic();popup=background_skill_button_rects(current) is not None
            ready_after=background_ready_slots(current)
            observed=None if popup or background_battle_animating(current) else background_skill_board_sample(current)
            changed=[]
            if baseline is not None and observed is not None:
                changed=[i for i,(a,b) in enumerate(zip(baseline['board'],observed['board'])) if a is not None and b is not None and a!=b]
            board_evidence=len(changed)>=3 and bool(effects.intersection(('refresh','five_board')))
            cooldown=None;readings=[]
            if not popup and slot not in ready_after and not board_evidence:
                cx=round((.057+.0875*slot)*1600);crop=current.crop((cx+26,650,cx+65,691))
                key=hashlib.sha256(crop.tobytes()).hexdigest()
                if key not in counter_cache:
                    for scale in (3,4):
                        values={int(_compact_ocr_text(t.text)) for t in self._run_ocr_tokens(crop.resize((crop.width*scale,crop.height*scale),Image.Resampling.LANCZOS))
                                if t.score>=.90 and re.fullmatch(r'\d{1,2}',_compact_ocr_text(t.text)) and 0<int(_compact_ocr_text(t.text))<=99}
                        readings.append(sorted(values))
                    common=set(readings[0])&set(readings[1]);counter_cache[key]=(next(iter(common)) if len(common)==1 else None,readings)
                cooldown,readings=counter_cache[key]
            after_time=timer(current) if 'time' in effects and not popup else None
            reason=('observed_cooldown' if cooldown is not None else
                    'board_effect' if board_evidence else
                    'time_increased' if baseline_time is not None and after_time is not None and after_time>baseline_time+.5 else None)
            signature=(tuple(observed['board']),tuple(observed['spikes']),reason,cooldown) if observed is not None and reason else None
            confirmed=signature is not None and signature==previous and not popup
            history.append(dict(check=attempt+1,popup=popup,ready_slots=list(ready_after),cooldown=cooldown,cooldown_readings=readings,
                changed_cells=changed,time_before=baseline_time,time_after=after_time,evidence=reason,stable=confirmed))
            if isinstance(snapshot,dict):snapshot.update(phase='background_skill_confirm',skill_after_image=current.copy(),input_observed_image=current.copy(),
                input_display=dict(device.input_diagnostics),input_trace=list(device.input_trace),skill_ready_after=list(ready_after),
                skill_confirm_checks=attempt+1,skill_popup_remaining=popup,skill_confirm_history=history,
                skill_confirm_seconds=round(time.monotonic()-started,3),skill_timer_cache_hits=timer_cache_hits,skill_confirm_limit_seconds=4.0)
            if confirmed:
                self._background_skill_confirmed_frame=dict(device=device,frame=current,observed=observed,captured_at=captured_at)
                return True
            previous=signature
        if popup:raise RuntimeError('사용하기 이후 팝업 유지 · 재클릭하지 않고 중지했습니다.')
        if isinstance(snapshot,dict):snapshot.update(phase='background_skill_no_effect',failure_image=current.copy(),failure_image_scope='skill_confirmation_last_frame',skill_failure_kind='popup_closed_without_confirmed_effect')
        raise RuntimeError('스킬 팝업은 닫혔지만 쿨타임·판·시간 효과가 확인되지 않았습니다. 재사용하지 않고 중지합니다.')

    def _background_wait_skill_board(self,device,before,effects):
        started=time.monotonic();previous=None
        needs_change=('refresh' in effects or 'five_board' in effects and not five_attribute_possible_by_count(before))
        confirmed=self.__dict__.pop('_background_skill_confirmed_frame',None)
        if (isinstance(confirmed,dict) and confirmed.get('device') is device
                and 0<=started-confirmed.get('captured_at',-1)<=1.0):
            observed=confirmed.get('observed')
            if isinstance(observed,dict) and 'board' in observed and 'spikes' in observed:
                previous=(tuple(observed['board']),tuple(observed['spikes']),tuple(observed.get('cloud_mask',[])))
        for _ in range(24):
            if self._background_cancel.wait(.08):raise RuntimeError('재료 파밍을 중지했습니다.')
            frame=device.capture();observed=None if background_battle_animating(frame) else background_skill_board_sample(frame)
            signature=(tuple(observed['board']),tuple(observed['spikes']),tuple(observed.get('cloud_mask',[]))) if observed is not None else None
            changed=signature is not None and any(value is not None and value!=before[i] for i,value in enumerate(signature[0]))
            cleared=True
            if signature is not None and set(effects)&{'bind_clear','awoken_clear','cleanse'}:
                state=self._background_visual_status(frame)
                cleared=not ((set(effects)&{'bind_clear','cleanse'} and state.get('bound'))
                             or (set(effects)&{'awoken_clear','cleanse'} and state.get('awoken_void')))
            if signature is not None and signature==previous and (not needs_change or changed) and cleared:
                diagnostics=getattr(self,'_background_diagnostics',None)
                if isinstance(diagnostics,dict):diagnostics['skill_board_settle_seconds']=round(time.monotonic()-started,3)
                return frame
            previous=signature
        raise RuntimeError('스킬 사용 후 판 변경·안정 또는 바인드·각성무효 해제를 확인하지 못했습니다.')

    def _background_prepare_cursor(self,rect):
        if getattr(self,'_background_cursor_prepared',False):return
        assert_action_active(self)
        if sys.platform!='win32':result=dict(moved=False,reason='not_windows')
        else:
            context=getattr(self,'_background_context',None)
            info=None if context else find_emulator_window_info()
            if context:hwnd,window_rect=context
            else:hwnd,window_rect=(info or {}).get('hwnd'),(info or {}).get('rect')
            result=input_core.park_background_cursor(hwnd,window_rect,rect) if window_rect else dict(moved=False,reason='window_unavailable')
        assert_action_active(self)
        self._background_cursor_prepared=True
        self._background_diagnostics=getattr(self,'_background_diagnostics',{})
        self._background_diagnostics['cursor_preparation']=result
        for snapshot in (getattr(self,'_farming_error_snapshot',None),getattr(self,'_manual_error_snapshot',None)):
            if isinstance(snapshot,dict):snapshot['cursor_preparation']=dict(result)

    def _background_team_goals(self,tokens):
        text=_compact_ocr_text(' '.join(t.text for t in tokens if t.score>=.82 and 480<t.cy<740))
        goals=self._background_run_goals
        if re.search(r'5(?:개)?속성.*(?:동시|공격)',text):
            if re.search(r'남은조작시간[이가]*4초이상',text) and re.search(r'6콤보이상',text):goals=master_multicolor_goals()
            elif not master_multicolor(goals):goals=(False,False,True,False,False,False,False)
        found=re.search(r'(\d{1,2})콤보이상',text)
        required=int(found.group(1)) if found and 1<=int(found.group(1))<=15 else 0
        return goals,required

    def _background_low_hp(self,frame):
        rail=route_health_status(frame)
        if rail.get('ratio') is not None:
            if rail['ratio']<.43:return True
            if rail['ratio']>.47:return False
        crop=frame.crop((580,875,855,930))
        readings=[]
        for scale in (3,4):
            text,score=self._recognize_title_line(crop.resize((crop.width*scale,crop.height*scale),Image.Resampling.LANCZOS))
            found=re.fullmatch(r'\s*(\d{1,7})\s*/\s*(\d{1,7})\s*',text)
            readings.append(tuple(map(int,found.groups())) if found and score>=.85 else None)
        return (len(readings)==2 and readings[0] is not None and readings[0]==readings[1]
                and 0<readings[0][1] and readings[0][0]/readings[0][1]<.45)

    def _background_status_text(self,frame):
        assert_action_active(self)
        crop=frame.crop((0,40,1600,255)).convert('RGB')
        key=(getattr(self,'_stop_epoch',0),hashlib.sha256(crop.tobytes()).digest())
        cache=getattr(self,'_background_status_text_cache',{})
        if key in cache:return dict(cache[key])
        assert_action_active(self)
        state=background_status_text(self._run_ocr_tokens(crop))
        assert_action_active(self)
        if key[0]==getattr(self,'_stop_epoch',0):
            cache[key]=dict(state);self._background_status_text_cache=dict(list(cache.items())[-4:])
        return state

    def _background_skill_context(self,frame,board,profiles,goals,seconds,required,bonus,shortage,applied,used,search_failed=False,*,enemy_combo_required=0,spikes=None,lock_count=None,lock_route_pending=False):
        # Stored party effects only; never open cards to discover skills in battle.
        if not any(p.get('effects') and p.get('auto_use',True) for p in profiles):
            self._last_background_skill_decision=None
            return {},[],None,''
        settings=getattr(self,'_background_run_settings',{})
        possible=sum(board.count(c)//3 for c in COLOR_ORDER)+bonus
        status_effects={'cleanse','bind_clear','awoken_clear','void_pierce','attack','recovery','absorb','attribute_absorb'}
        state=self._background_visual_status(frame)
        visual_counter=any(state.get(k) for k in ('void_shield','bound','awoken_void','damage_absorb','attribute_absorb'))
        time_issue=seconds is None and shortened_timer_bar(frame) or seconds is not None and seconds<6
        if not (visual_counter or time_issue) and any(status_effects.intersection(p.get('effects',[])) for p in profiles):
            text_state=self._background_status_text(frame)
            for flag,value in text_state.items():state[flag]=state.get(flag,False) or value
        state.update(shortage=shortage,rainbow=bool(goals[2]),short_time=bool(state.get('time_reduction')) or (seconds is not None and seconds<min(6.0,float(settings.get('background_normal_seconds',10)))) or (seconds is None and master_multicolor(goals) and shortened_timer_bar(frame)),
                     combo_short=bool(enemy_combo_required>0 and bonus<=0),
                     locked=(background_lock_count(frame) if lock_count is None else lock_count)>0,
                     spike_count=sum(bool(value) for value in (spikes or [])),
                     enemy_combo_required=enemy_combo_required,
                     low_hp=self._background_low_hp(frame) if not visual_counter and not time_issue and any('heal' in p.get('effects',[]) or 'shield' in p.get('effects',[]) for p in profiles) else False)
        state['spikes_many']=state['spike_count']>=6
        state['lock_route_pending']=bool(lock_route_pending and state['locked'] and not search_failed)
        state['time_critical']=master_multicolor(goals) and ((seconds is not None and seconds<=5.0) or (seconds is None and shortened_timer_bar(frame)))
        state['search_failed']=search_failed
        # Piercing/bonus are active buffs while the enemy badge remains visible.
        # Cleansing and unlock must instead follow the new observed board/status.
        for flag,effect in (('void_shield','void_pierce'),('damage_absorb','absorb'),('attribute_absorb','attribute_absorb'),('attack_down','attack'),('combo_short','bonus')):
            if effect in applied:state[flag]=False
        ready=self._background_needed_ready_slots(frame,profiles,state,used)
        needed=set(background_skill_needs(state))
        if needed or search_failed:
            counts=getattr(self,'_background_cooldown_readings',{}).get('counts',{})
            targets={}
            for slot in ready:
                turns=int(profiles[slot].get('haste_turns') or 0)
                if 'haste' not in profiles[slot].get('effects',[]) or turns<=0:continue
                # Partial progress (e.g. 2 -> 1) is useful too. Never use catalog
                # cooldowns or an unread/ambiguous current count as proof.
                waiting=[i for i,count in counts.items() if i!=slot and i not in used and count>0
                         and set(profiles[i].get('effects',[])).intersection(needed)
                         and profiles[i].get('auto_use',True) is not False
                         and not (profiles[i].get('requires_confirmation') and not profiles[i].get('verified'))
                         and background_skill_decision(profiles,[i],state,used)[0]==i]
                if waiting:targets[slot]=waiting
            state['counter_haste_slots']=list(targets)
            state['counter_haste_targets']=targets
            state['cooldown_remaining']=dict(counts)
        choice,reason=background_skill_decision(profiles,ready,state,used)
        self._last_background_skill_decision=dict(state=dict(state),ready=list(ready),choice=choice,reason=reason,readiness={k:v for k,v in getattr(self,'_background_cooldown_readings',{}).items() if k!='frame'},profiles=[dict(number=p.get('number'),name=p.get('name'),effects=p.get('effects',[]),haste_turns=p.get('haste_turns',0),haste_source=p.get('haste_source'),auto_use=p.get('auto_use',True)) for p in profiles])
        return state,ready,choice,reason

    def _background_cache_input_failure(self,device,error):
        """Preserve the last owned pixels and optionally compare a released frame.

        The gesture has already released its finger by the time it raises, but
        these pixels were captured before that release. Keep that distinction
        explicit; the outer worker's frame may predate a board-changing skill.
        """
        snapshot=getattr(self,'_farming_error_snapshot',None)
        if not isinstance(snapshot,dict):snapshot={};self._farming_error_snapshot=snapshot
        diagnostics=dict(getattr(device,'input_diagnostics',{}) or {})
        snapshot.update(input_error=str(error),input_trace=list(getattr(device,'input_trace',[])),
            input_display=diagnostics,input_game_confirmed=False)
        feedback=diagnostics.get('control_start_feedback') or diagnostics.get('sdk_start_feedback') or {}
        if (feedback.get('reason')=='start_unchanged' and feedback.get('unchanged_cells')==30
                and diagnostics.get('sdk_release_confirmed') is True
                and not self._background_cancel.is_set()):
            try:
                independent=device.capture_independent_failure()
                if isinstance(independent,Image.Image):
                    original=getattr(device,'last_before_up_frame',None)
                    difference=None
                    if isinstance(original,Image.Image) and original.size==independent.size:
                        difference=float(np.abs(np.asarray(original,dtype=np.int16)-np.asarray(independent,dtype=np.int16)).mean())
                    snapshot.update(input_independent_image=independent,
                        input_independent_capture=dict(source='adb_png_after_release',sdk_difference_mae=difference,
                            same_pixels=difference==0 if difference is not None else None))
            except Exception as diagnostic_error:
                snapshot['input_independent_capture']=dict(source='adb_png_after_release',error=str(diagnostic_error))
        released=getattr(device,'last_after_release_frame',None)
        if isinstance(released,Image.Image):
            snapshot.update(input_release_image=released.copy(),input_failure_post_release_observed=True)
        held=getattr(device,'last_before_up_frame',None)
        if isinstance(held,Image.Image):
            feedback=diagnostics.get('control_start_feedback') or diagnostics.get('sdk_start_feedback') or {}
            control=diagnostics.get('input_transport') in ('android_verified_batch','android_control') or str(diagnostics.get('input_transport','')).startswith('maa_')
            scope=('touch_start_check' if control else 'sdk_start_check') if feedback.get('confirmed') is False else ('before_touch_up' if control else 'before_sdk_up')
            snapshot.update(input_before_up_image=held.copy(),input_observed_image=held.copy(),
                input_observation_scope=scope,failure_image=held.copy(),failure_image_scope=scope+'_before_release')

    def _background_battle_turn(self,device,frame,profiles,goals,team_min,initial_observed=None):
        if background_battle_intro(frame) or background_battle_animating(frame):return False
        if master_multicolor(goals):
            # The run may have started at low HP; re-evaluate the adaptive
            # heart requirement every turn rather than latching it for the run.
            values=list(goals);values[3]=False;goals=tuple(values)
        # UI publishes an immutable request. Apply only at a new turn boundary,
        # before computing its path/time budget; never mutate an active gesture.
        pending=getattr(self,'_background_timing_request',None)
        if pending is not None and pending is not getattr(self,'_background_timing_applied',None):
            device.capture_settings.update(pending)
            self._background_run_settings.update(pending)
            self._background_timing_applied=pending
            device.input_diagnostics['maa_requested_timing']=dict(pending)
            timing=input_core.maa_playback_timing(device)
            self._background_queue.put(('status',f'입력 속도 적용 · {timing["sample_seconds"]*1000:g}ms · 다음 경로 계산'))
        turn_started=time.monotonic()
        used=set()
        applied=set()
        math_spent=0.0;casts=0;searches=0;skill_trace=[];observation_seconds=0.0
        for attempt in range(12):
            if self._background_cancel.is_set():return False
            if attempt and background_battle_animating(frame):return False
            # A previous turn/stage's recommendation is not this frame's decision.
            self._last_background_skill_decision=None
            visual=self._background_visual_status(frame)
            ally_disabled=bool(visual.get('bound') or visual.get('awoken_void'))
            urgent_effects={effect for flag,effect in
                (('void_shield','void_pierce'),('damage_absorb','absorb'),('attribute_absorb','attribute_absorb'))
                if visual.get(flag) and effect not in applied}
            urgent_enemy=bool(urgent_effects and any(profile.get('auto_use',True) and
                set(profile.get('effects',[])).intersection(urgent_effects|{'haste'}) for profile in profiles))
            if ally_disabled or urgent_enemy:
                # Confirmed visual counters can act before combo/time OCR.
                # No colour guess is needed to select the highest-priority
                # cleanse, or haste backed by observed remaining cooldowns.
                state,ready,choice,reason=self._background_skill_context(frame,[],profiles,goals,None,0,0,False,applied,used)
                # A locked board alone needs the normal route check. This
                # early path only bypasses OCR for an observed urgent counter.
                if choice is not None and not ally_disabled:
                    effects=set(profiles[choice].get('effects',[]))
                    urgent_haste='haste' in effects and any(set(profiles[i].get('effects',[])).intersection(urgent_effects)
                        for i in state.get('counter_haste_targets',{}).get(choice,[]))
                    if not (effects.intersection(urgent_effects) or urgent_haste or 'time' in effects and state.get('time_critical')):
                        choice=None
                snapshot=dict(board=[],path=[],spikes=[],entry_image=getattr(self,'_background_entry_diagnostics_image',None))
                snapshot.update(phase='background_cleanse' if ally_disabled else 'background_counter',game_image=frame.copy(),goals=list(goals),
                    source='adb_background',version=APP_VERSION,skill_trace=list(skill_trace),
                    skill_decision=getattr(self,'_last_background_skill_decision',None) or dict(choice=None,
                        reason='사용 가능한 자동 스킬 효과 미등록 또는 꺼짐',profiles=[dict(slot=i,name=p.get('name'),effects=p.get('effects',[]),auto_use=p.get('auto_use',True)) for i,p in enumerate(profiles)]),ally_status=dict(visual))
                self._farming_error_snapshot=snapshot
                if ally_disabled and (choice is None or casts>=8):
                    raise RuntimeError('바인드·각성무효 우선 해제 · 사용 가능한 해제/단축 스킬을 확인하지 못해 입력을 중지했습니다.')
                if choice is not None and casts<8:
                    effects=profiles[choice].get('effects',[])
                    baseline=background_skill_board_sample(frame) if set(effects).intersection(('refresh','five_board')) else None
                    before=baseline['board'] if baseline is not None else [None]*30
                    skill_trace.append(dict(slot=choice,name=profiles[choice].get('name'),reason=reason,state=dict(state),preflight=True))
                    snapshot['skill_trace']=list(skill_trace)
                    label='바인드·각성무효 우선 대응' if ally_disabled else '적 효과 우선 대응'
                    self._background_queue.put(('status',f'{label} · {profiles[choice].get("name",choice+1)} · {reason} · F10 중지'))
                    used.add(choice);casts+=1
                    self._invalidate_cloud_board()
                    assert_action_active(self)
                    if not self._background_use_skill(device,frame,choice):raise RuntimeError(label+' 스킬 발동을 확인하지 못했습니다.')
                    applied.update(effects)
                    if 'haste' in effects:used={i for i in used if 'haste' in profiles[i].get('effects',[])}
                    frame=self._background_wait_skill_board(device,before,effects)
                    math_spent=0.0;searches=0
                    continue
            observation_started=time.monotonic()
            # The worker already validated this exact frame for stability.
            # Skills and all later captures must obtain their own observation.
            observed=initial_observed if attempt==0 and initial_observed is not None else self._background_observed(frame,device,True)
            observation_seconds+=time.monotonic()-observation_started
            if observed is None:return False
            board,spikes=observed['board'],observed['spikes']
            # Hidden, unobserved thorns are conservative search flags rather
            # than evidence that a board-destruction skill is needed.
            unknown_spikes=set((observed.get('cloud_diagnostics') or {}).get('spikes_unconfirmed') or [])
            skill_spikes=[bool(value) and i not in unknown_spikes for i,value in enumerate(spikes)]
            health=App._observe_route_health(self,frame)
            search_spikes=App._route_search_spikes(self,spikes,unconfirmed=unknown_spikes)
            recovery_required=master_multicolor(goals) and health.get('low_hp') is True
            condition=self._read_combo_condition(frame,board,store=False)
            self._manual_error_snapshot=dict(board=list(board),board_image=observed['crop'].copy(),game_image=frame.copy(),
                path=[],spikes=list(spikes),goals=list(goals),combo_condition=condition,phase='background_search',
                source='adb_background',version=APP_VERSION,health=dict(health),recovery_required=recovery_required,board_rect=list(observed['rect']),
                entry_image=getattr(self,'_background_entry_diagnostics_image',None),
                timings=dict(getattr(self,'_background_diagnostics',{})),input_display=getattr(device,'input_diagnostics',{}),
                input_trace=getattr(device,'input_trace',[]),
                cloud_mask=observed.get('cloud_mask',[]),cloud_observation=observed.get('cloud_observation'),cloud_diagnostics=observed.get('cloud_diagnostics'),skill_trace=list(skill_trace),captured_local=time.strftime('%Y-%m-%d %H:%M:%S'))
            self._farming_error_snapshot=dict(self._manual_error_snapshot)
            self._background_queue.put(('board',board,spikes,observed['crop'].copy()))
            if not condition['confirmed']:
                if not master_multicolor(goals):raise RuntimeError('적 콤보 조건 미확인 · 파밍을 중지했습니다.')
                # Resolve the icon floor before timer OCR, skills or an expensive
                # attack search. Duration digits are never a substitute floor.
                condition_started=time.monotonic();condition_reads=[dict(condition)]
                condition_changed=False
                self._background_queue.put(('status','적 콤보 조건 재확인 · 최대 3회 · F10 중지'))
                for retry in range(2):
                    if self._background_cancel.wait(.10):return False
                    if time.monotonic()-condition_started>=4.0:break
                    fresh=device.capture();observation_started=time.monotonic()
                    latest=self._background_observed(fresh,device,True)
                    observation_seconds+=time.monotonic()-observation_started
                    if latest is None:return False
                    frame=fresh
                    if (latest['board']!=board or latest['spikes']!=spikes
                            or tuple(latest['rect'])!=tuple(observed['rect'])):
                        condition_changed=True;break
                    observed=latest
                    try:condition=self._read_combo_condition(frame,board,store=False)
                    except Exception as exc:condition=dict(condition,confirmed=False,error=str(exc))
                    condition_reads.append(dict(condition))
                    if condition['confirmed'] or time.monotonic()-condition_started>=4.0:break
                for snapshot in (self._manual_error_snapshot,self._farming_error_snapshot):
                    snapshot.update(combo_condition=condition,combo_condition_reads=condition_reads,
                        combo_condition_elapsed=round(time.monotonic()-condition_started,3),
                        game_image=frame.copy(),board_image=observed['crop'].copy())
                if condition_changed:continue
                if not condition['confirmed']:
                    for snapshot in (self._manual_error_snapshot,self._farming_error_snapshot):
                        snapshot['phase']='background_condition_unconfirmed'
                    raise RuntimeError('적 콤보 조건 미확인 · 최대 3회/4초 재확인 종료 · 숫자를 추측하지 않고 파밍을 중지했습니다.')
            _,seconds=self._restricted_drag_move_cap(image=frame,report=False)
            timer_reads=[dict(getattr(self,'_last_timer_read',{}))]
            obscured_timer=any(len(read)>2 and read[2]=='시간 감소 화살표가 숫자를 가림' for read in getattr(self,'_last_timer_read',{}).get('readings',[]))
            if seconds is None and master_multicolor(goals) and not obscured_timer:
                changed=False
                for retry in range(2):
                    if self._background_cancel.wait(.12):return False
                    frame=device.capture();observation_started=time.monotonic()
                    latest=self._background_observed(frame,device,True)
                    observation_seconds+=time.monotonic()-observation_started
                    if latest is None:return False
                    if latest['board']!=board or latest['spikes']!=spikes:
                        changed=True;break
                    _,seconds=self._restricted_drag_move_cap(image=frame,report=False)
                    timer_reads.append(dict(getattr(self,'_last_timer_read',{})))
                    if seconds is not None:break
                if changed:continue
                # Preserve the exact latest image and every failed read for diagnosis.
                for snapshot in (self._manual_error_snapshot,self._farming_error_snapshot):
                    snapshot.update(game_image=frame.copy(),board_image=latest['crop'].copy())
            self._farming_error_snapshot.update(timer_reads=timer_reads,timer_seconds=seconds)
            required=max(team_min,condition['required_total'],6 if master_multicolor(goals) else 0);bonus=condition['combo_bonus']
            shortage=bool(goals[2] and not five_attribute_possible_by_count(board))
            possible=sum(board.count(c)//3 for c in COLOR_ORDER)+bonus
            settings=getattr(self,'_background_run_settings',{})
            short_time=(seconds is not None and seconds<min(6.0,float(settings.get('background_normal_seconds',10)))) or (seconds is None and master_multicolor(goals) and shortened_timer_bar(frame))
            state={};ready=[];choice=None;reason=''
            # Check current obstacles even when there are already five colours.
            # Ordinary board-only skills still wait until a board is deficient.
            visual=self._background_visual_status(frame)
            lock_count=background_lock_count(frame)
            spikes_many=sum(skill_spikes)>=6
            lock_counter=lock_count>0 and any('unlock' in profile.get('effects',[]) for profile in profiles)
            spike_counter=spikes_many and any('refresh' in profile.get('effects',[]) for profile in profiles)
            enemy_combo=(condition['required_total']>0 and bonus<=0 and 'bonus' not in applied
                         and any('bonus' in profile.get('effects',[]) and profile.get('auto_use',True) for profile in profiles))
            critical_counter=any(visual.get(flag) and (effect not in applied or flag in ('bound','awoken_void')) for flag,effect in (('void_shield','void_pierce'),('damage_absorb','absorb'),('attribute_absorb','attribute_absorb'),('bound','bind_clear'),('awoken_void','awoken_clear')))
            refresh_locks=bool(lock_counter and 'refresh' in applied and 'unlock' not in applied)
            # Enough colours are permission to try the normal search, not proof
            # of a valid route. Spend unlock only if that actual search fails.
            lock_route_pending=bool(lock_counter and goals[2] and not shortage and possible>=required and not short_time
                                    and seconds is not None and seconds>=6 and not critical_counter and not refresh_locks)
            if shortage or possible<required or short_time or critical_counter or (lock_counter and not lock_route_pending) or spike_counter or enemy_combo or visual.get('time_reduction'):
                state,ready,choice,reason=self._background_skill_context(frame,board,profiles,goals,seconds,required,bonus,shortage,applied,used,
                    enemy_combo_required=condition['required_total'],spikes=skill_spikes,lock_count=lock_count,lock_route_pending=lock_route_pending)
                critical_counter=critical_counter or any(state.get(flag) for flag in ('void_shield','damage_absorb','attribute_absorb','bound','awoken_void'))
                self._farming_error_snapshot['skill_decision']=getattr(self,'_last_background_skill_decision',None)
                if state.get('bound') or state.get('awoken_void'):
                    # A fresh status discovered during a recapture returns to
                    # the ally-first path instead of spending an attack skill.
                    continue
            if choice is not None and casts<8:
                self._farming_error_snapshot.update(skill_reason=reason,skill_effects=profiles[choice].get('effects',[]),skill_decision=getattr(self,'_last_background_skill_decision',None))
                skill_trace.append(dict(slot=choice,name=profiles[choice].get('name'),reason=reason,seconds=seconds,shortage=shortage,critical_counter=critical_counter,state=dict(state)))
                self._farming_error_snapshot['skill_trace']=list(skill_trace)
                used.add(choice);casts+=1
                self._background_queue.put(('status',f'자동 스킬 · {profiles[choice]["name"]} · {reason} · F10 중지'))
                self._invalidate_cloud_board()
                if not self._background_use_skill(device,frame,choice):raise RuntimeError('스킬 발동을 확인하지 못해 파밍을 중지했습니다.')
                applied.update(profiles[choice].get('effects',[]))
                if 'haste' in profiles[choice].get('effects',[]):used={i for i in used if 'haste' in profiles[i].get('effects',[])}
                frame=self._background_wait_skill_board(device,board,profiles[choice].get('effects',[]))
                math_spent=0.0;searches=0
                self._background_queue.put(('status','스킬 사용 완료 · 판 안정 확인 · 재계산 · F10 중지'))
                continue
            if master_multicolor(goals) and seconds is None:
                raise RuntimeError('조작시간 숫자 재확인 실패 · 시간 감소 표시/숫자 겹침을 확인하세요. 사용 가능한 시간 대응 스킬이 없어 4초 잔여 조건을 보장할 수 없습니다.')
            survival=master_multicolor(goals) and seconds is not None and (shortage or seconds<=5.0 or critical_counter) and not recovery_required
            if recovery_required and (shortage or seconds is not None and seconds<=5.0 or board.count('H')<3):
                missing=[f'{COLOR_INFO[c][0]} {board.count(c)}개/필요 3개' for c in ('R','B','G','Y','P','H') if board.count(c)<3]
                if seconds is not None and seconds<=5.0:missing.append(f'조작시간 {seconds:g}초')
                detail=' · '.join(missing)
                self._farming_error_snapshot.update(phase='background_recovery_requirements',
                    recovery_blockers=dict(counts={c:board.count(c) for c in ('R','B','G','Y','P','H')},
                        missing=missing,timer_seconds=seconds,health=dict(health)),
                    failure_image=frame.copy(),failure_image_scope='recovery_requirement_check')
                raise RuntimeError('체력 60% 이하 · 회복 포함 5속성·6콤보 조건 부족 · '+detail+' · 사용 가능한 대응 스킬 없음 · 파밍 중지')
            operation_seconds=route_operation_seconds(seconds,master_survival_goals() if survival else goals)
            cap=device.move_cap(operation_seconds)
            self._farming_error_snapshot.update(search_move_cap=cap,search_operation_seconds=operation_seconds,skill_decision=getattr(self,'_last_background_skill_decision',None))
            effective=master_survival_goals(required,bonus) if survival else tuple(False for _ in goals) if (shortage or critical_counter) and not recovery_required else goals
            # With no useful skill and insufficient colours, charge skills by playing combos.
            combo_turn=(shortage or critical_counter) and choice is None and not master_multicolor(goals)
            effective=recovery_route_goals(effective,recovery_required)
            target=combo_condition_goals(effective,6 if combo_turn else required,bonus)
            if recovery_required:self._background_queue.put(('status','체력 60% 이하 · 회복 포함 5속성·6콤보 경로 탐색 · F10 중지'))
            if survival:self._background_queue.put(('status','달인 다색 · 공격 조건 부족 · 6콤보 이상 생존 경로 · F10 중지'))
            if combo_turn:self._background_queue.put(('status','5속성 부족 · 사용 가능한 대응 스킬 없음 · 6콤보 이상으로 턴 진행 · F10 중지'))
            if not combo_turn:self._background_queue.put(('status',f'백그라운드 경로 탐색 · 적/팀 {required}콤보 이상 · 가산 +{bonus} · F10 중지'))
            search_ceiling=7.0 if master_multicolor(goals) and not survival else 8.0
            budget=min(route_search_budget(seconds,3.0 if searches==0 else 1.0),max(0.0,search_ceiling-math_spent))
            if budget<=0:raise RuntimeError('탐색 실패 · 계산 대기 한도 도달 · 파밍 중지')
            math_started=time.monotonic();searches+=1
